/**
 * Build the internal pages (pab://newtab, pab://search) as static HTML for
 * the TAURI runtime — generated by the SAME TS builders the Electron
 * runtime serves, so the two runtimes render identical pages.
 *
 * Output: .vite/build/internal/newtab.html | search.html
 *   - newtab.html: rendered with EMPTY top-sites + a deferred-fetch bootstrap
 *     (the Tauri runtime serves `api/topsites` + `api/news` from Rust).
 *   - search.html: rendered with __PAB_PERPLEXICA_URL__ / __PAB_PERPLEXICA_MODEL__
 *     placeholders the Rust pab:// handler substitutes at serve time.
 *
 * Requires: node_modules/.bin/esbuild (shipped with vite).
 */
import { execFileSync } from 'node:child_process';
import { mkdirSync, writeFileSync, rmSync, readFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const appRoot = resolve(here, '..');
const outDir = join(appRoot, '.vite', 'build', 'internal');
const tmpDir = join(appRoot, '.vite', 'internal-pages-build');
const fwd = (p) => p.replace(/\\/g, '/');

mkdirSync(outDir, { recursive: true });
mkdirSync(tmpDir, { recursive: true });

// The deferred top-sites bootstrap injected into the Tauri newtab page.
// Builds the same tile markup the server-side builder uses, from the live
// `api/topsites` JSON (served by the Rust runtime from the history store).
const deferredJs = `<script>
(function () {
  fetch('api/topsites')
    .then(function (r) { return r.json(); })
    .then(function (j) {
      var sites = (j && j.topSites) || [];
      if (!sites.length) return;
      var main = document.querySelector('main.content');
      if (!main) return;
      var wrap = document.createElement('div');
      wrap.className = 'sites';
      var label = document.createElement('div');
      label.className = 'sites__label';
      label.textContent = 'FREQUENT SITES';
      var grid = document.createElement('div');
      grid.className = 'grid';
      sites.slice(0, 8).forEach(function (s) {
        var a = document.createElement('a');
        a.className = 'tile';
        a.href = s.url;
        a.title = s.url;
        var host = document.createElement('span');
        host.className = 'tile__host';
        host.textContent = s.host || s.url;
        var title = document.createElement('span');
        title.className = 'tile__title';
        title.textContent = s.title || s.url;
        a.appendChild(host);
        a.appendChild(title);
        grid.appendChild(a);
      });
      wrap.appendChild(label);
      wrap.appendChild(grid);
      main.appendChild(wrap);
    })
    .catch(function () {});
})();
</script>`;

writeFileSync(join(tmpDir, 'deferred-topsites.js'), deferredJs, 'utf8');

// Brand logo for pab://darkweb — embedded as a data: URL so the page stays
// a single self-contained HTML file (the Rust handler serves it verbatim).
const darkwebLogo =
  'data:image/jpeg;base64,' +
  readFileSync(join(appRoot, 'resources', 'brand', 'darkwebsearch.jpg')).toString('base64');

const entryLines = [
  "import { writeFileSync, readFileSync } from 'node:fs';",
  `import { buildNewTabHtml } from '${fwd(join(appRoot, 'src/main/browser/pure/newtab-page.ts'))}';`,
  `import { buildSearchPageHtml } from '${fwd(join(appRoot, 'src/main/browser/pure/search-page.ts'))}';`,
  `import { buildDarkWebPageHtml } from '${fwd(join(appRoot, 'src/main/browser/darkweb/pure/darkweb-page.ts'))}';`,
  `const deferred = readFileSync('${fwd(join(tmpDir, 'deferred-topsites.js'))}', 'utf8');`,
  `const outDir = '${fwd(outDir)}';`,
  `let newtab = buildNewTabHtml([], []);`,
  `newtab = newtab.replace('</body>', deferred + '\\n</body>');`,
  `writeFileSync(outDir + '/newtab.html', newtab);`,
  `const search = buildSearchPageHtml({`,
  `  perplexicaURL: '__PAB_PERPLEXICA_URL__',`,
  `  modelKey: '__PAB_PERPLEXICA_MODEL__',`,
  `});`,
  `writeFileSync(outDir + '/search.html', search);`,
  `writeFileSync(outDir + '/darkweb.html', buildDarkWebPageHtml('${darkwebLogo}'));`,
  `console.log('internal pages written');`,
];
writeFileSync(join(tmpDir, 'entry.ts'), entryLines.join('\n'), 'utf8');

const bundle = join(tmpDir, 'bundle.cjs');
execFileSync(
  'node_modules/.bin/esbuild',
  ['--bundle', join(tmpDir, 'entry.ts'), `--outfile=${bundle}`, '--format=cjs', '--platform=node', '--log-level=error'],
  { cwd: appRoot, stdio: 'inherit' }
);
execFileSync('node', [bundle], { cwd: appRoot, stdio: 'inherit' });

// Honest artifact verification — refuse to ship a broken internal page.
const newtabHtml = readFileSync(join(outDir, 'newtab.html'), 'utf8');
if (!newtabHtml.includes('<!doctype html>') || newtabHtml.length < 10000 || !newtabHtml.includes('api/topsites')) {
  throw new Error('newtab.html failed verification');
}
const searchHtml = readFileSync(join(outDir, 'search.html'), 'utf8');
if (!searchHtml.includes('__PAB_PERPLEXICA_URL__') || !searchHtml.includes('__PAB_PERPLEXICA_MODEL__')) {
  throw new Error('search.html is missing the runtime placeholders');
}
const darkwebHtml = readFileSync(join(outDir, 'darkweb.html'), 'utf8');
if (!darkwebHtml.includes('<!doctype html>') || darkwebHtml.length < 5000 || !darkwebHtml.includes('/api/') || !darkwebHtml.includes('data:image/jpeg;base64,')) {
  throw new Error('darkweb.html failed verification');
}
rmSync(join(tmpDir), { recursive: true, force: true });
console.log('[internal-pages] OK:', fwd(join(outDir, 'newtab.html')), '+ search.html + darkweb.html');
